(91, 'API LIFE AAYUH GOLDFISH FOOD (AAYUH) large', '<ul><li>THIS FISH FOOD CAN PARTICULARLY BE USED FOR COLOR ENHANCEMENT FOR YOUR FISH AND CAN BE INCLUDED TWICE A WEEK IN THE DIET OF YOUR FISH.</li><li>IT WORKS AS AN IMMUNITY BOOSTER.</li><li>THIS FISH FOOD IS HANDMADE HAVING NATURAL AS WELL AS AYURVEDIC INGREDIENTS.</li><li>IT HAS CLINICALLY PROVEN CONTENT.</li><li>THIS FISH FOOD IS DIGESTION FRIENDLY AND KEEPS THE WATER CLEAN.</li></ul>', NULL, 'published', '[\"life-aayuh-goldfish-food-ayuh-600x600-1.png\"]', NULL, NULL, 0, 0, 0, 0, 1, 0, 0, 0, 293, 263.7, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 1, '2024-09-04 11:35:45', '2024-09-04 11:35:45', 'in_stock', 3, 'Botble\\ACL\\Models\\User', NULL, 'physical', NULL, NULL, 0, 0, 0, 0, NULL, 0, 0),
(92, 'API LIFE AAYUH GOLDFISH FOOD (AAYUH) MEDIUM', '<ul><li>THIS FISH FOOD CAN PARTICULARLY BE USED FOR COLOR ENHANCEMENT FOR YOUR FISH AND CAN BE INCLUDED TWICE A WEEK IN THE DIET OF YOUR FISH.</li><li>IT WORKS AS AN IMMUNITY BOOSTER.</li><li>THIS FISH FOOD IS HANDMADE HAVING NATURAL AS WELL AS AYURVEDIC INGREDIENTS.</li><li>IT HAS CLINICALLY PROVEN CONTENT</li><li>THIS FISH FOOD IS DIGESTION FRIENDLY AND KEEPS THE WATER CLEAN</li></ul>', NULL, 'published', '[\"happy-raksha-bandhan-instagram-post3-600x600.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 254, 228.6, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 1, '2024-09-04 18:10:28', '2024-09-04 18:10:28', 'in_stock', 3, 'Botble\\ACL\\Models\\User', NULL, 'physical', NULL, NULL, 0, 0, 0, 0, NULL, 0, 0),
(93, 'API LIFE AAYUH MARINE FISH FOOD (70GM) REGULAR', '<ol><li>IMMUNITY BOOSTER</li><li>HANDMADE</li><li>NATURAL</li><li>AYURVEDIC INGREDIENTS</li><li>CLINICALLY PROVEN CONTENT</li></ol>', NULL, 'published', '[\"marine-food-regular-300x300.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 0, 0, 0, 415, 373.5, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 2, '2024-09-04 18:19:08', '2024-09-04 18:19:08', 'out_of_stock', 3, 'Botble\\ACL\\Models\\User', NULL, 'physical', NULL, NULL, 0, 0, 0, 0, NULL, 0, 0),
(94, 'API LIFE AAYUH NEUTRAL FOOD (AAYUH) LARGE', '<ul><li>This fish food is particularly for all the SMALL fish which can be included in everyday diet of your fish. It works as an Immunity booster.</li><li>This Fish food is hand made having natural as well as Ayurvedic ingredients.</li><li>It has clinically proven content.</li><li>This fish food is digestion friendly and keeps the water clean.</li><li>Size : Small Pellet. Ideally suitable for Tetras, Beta Fish, Guppy</li></ul>', '', 'published', '[\"api-life-neutral-fish-food-ayuh-large-pellets-600x600.jpg\"]', NULL, NULL, 0, 0, 0, 0, 1, 1, 0, 0, 293, 263.7, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 9, '2024-09-04 18:22:00', '2024-10-07 12:11:36', 'out_of_stock', 3, 'Botble\\ACL\\Models\\User', 'api-life-neutral-fish-food-ayuh-large-pellets-600x600.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(95, 'API LIFE AAYUH NEUTRAL FOOD (AAYUH) SMALL', '<ul><li>This fish food is particularly for all the SMALL fish which can be included in everyday diet of your fish. It works as an Immunity booster.</li><li>This Fish food is hand made having natural as well as Ayurvedic ingredients.</li><li>It has clinically proven content.</li><li>This fish food is digestion friendly and keeps the water clean.</li><li>Size : Small Pellet. Ideally suitable for Tetras, Beta Fish, Guppy</li></ul>', '', 'published', '[\"api-life-neutral-fish-food-ayuh-small-pellets-600x600.jpg\"]', NULL, NULL, 0, 0, 0, 0, 1, 1, 0, 0, 236, 212.4, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 3, '2024-09-04 18:28:19', '2024-10-07 12:12:08', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'api-life-neutral-fish-food-ayuh-small-pellets-600x600.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(96, 'API LIFE AAYUH RED FISH FOOD (AAYUH) LARGE', '<ul><li>This fish food can particularly be used for Colour enhancement for BIG fish and can be included twice a week in the diet of your fish.</li><li>It works as an Immunity booster.</li><li>This Fish food is hand made having natural as well as Ayurvedic ingredients.</li><li>It has clinically proven content.</li><li>This fish food is digestion friendly and keeps the water clean.</li><li>Size : Large Pellet. Ideally suitable for Angels, Discus &amp; Cichlids</li></ul>', '', 'published', '[\"api-life-red-fish-food-ayuh-medium-pellets-600x600.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, 1, 0, 0, 390, 351, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 0, '2024-09-04 18:32:37', '2024-10-07 12:12:32', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'api-life-red-fish-food-ayuh-medium-pellets-600x600.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(97, 'API LIFE AAYUH SHRIMP FOOD REGULAR', '<ul><li class=\"a-unordered-list a-vertical a-spacing-mini\"><span class=\"a-list-item\">API Life Aayu Shrimp Food good for all kind of neocaridina shrimps</span></li><li class=\"a-unordered-list a-vertical a-spacing-mini\"><span class=\"a-list-item\">Best Shrimp food &amp; feed everyday for best growth.</span></li><li class=\"a-unordered-list a-vertical a-spacing-mini\"><span class=\"a-list-item\">Special Ingredients added to assist better breeding, molting &amp; growth.</span></li><li class=\"a-unordered-list a-vertical a-spacing-mini\"><span class=\"a-list-item\">Its Handmade, Immunity Booster &amp; natural Shrimp food.</span></li><li class=\"a-unordered-list a-vertical a-spacing-mini\"><span class=\"a-list-item\">Ayurvedic Ingredients &amp; Clinically Proven Shrimp food.</span></li></ul>', '', 'published', '[\"shrimp-food-300x300.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 1, 0, 0, 275, 250, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 5, '2024-09-04 18:36:45', '2024-10-07 12:12:57', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'shrimp-food-300x300.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(98, 'Intan Betta Pellets(27gm)', '<p class=\"fw600\" style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Floating Pellets</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Size #  1 mm Dia</p><ul><li>Contains ‘ Fresh Blood worms” that replicate natural diet</li><li>Fresh Chironomid Larvae &amp; astaxanthin for vivid coloration of Betta fish</li><li>Promotes growth and immunity against diseases</li><li>Highly nutritious daily diet for Fighter fish</li></ul><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Suitable for fighters like Crown tail, Long fin, Big eared, Koi fighters etc</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Intan Betta pellets are formulated exclusively with high-quality ingredients, ensuring a well-balanced diet. Since betta fish have short digestive tracts, the finest betta food replicates natural diet without adding indigestible fillers, so we have included sufficient bloodworms to replicate their natural diet. Fresh chironomid larvae and astaxanthin contribute to the hues and patterns</p>', '', 'published', '[\"intan-betta-pellets27gm-600x600.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 117, 100, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 2, '2024-09-04 18:38:24', '2024-10-05 14:42:01', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'intan-betta-pellets27gm-600x600.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(99, 'Intan Bits (Slow Sinking Crumble Feed) mini 20g', '<div class=\"product-details-module__title ec-header-h6\" style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Product Details</div><div class=\"product-details-module__content\" style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><div class=\"product-details__product-description\"><div><div>Intan Bits (Slow Sinking Crumble Feed) is a highly nutritious ornamental fish food that is suitable for all types of fish, including discus, danios, barbs, and rainbows. It is a balanced diet that contains a blend of crumbled and granulated feeds that can be crushed to any size. The food is made with Antarctic krill, a sustainable protein source that adds flavor and palatability, and astaxanthin, a natural source that enhances fish colors.</div></div></div></div>', '', 'published', '[\"untitled-design247-min-600x600-400x400-1.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 135, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 2, '2024-09-05 12:39:31', '2024-10-05 14:41:44', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'untitled-design247-min-600x600-400x400.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(100, 'Intan Bits large (110gm)', '<p class=\"fw600\" style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Slow Sinking Crushable Crumble</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Szie # 1.4 mm – 1.7 mm Dia</p><ul><li>Uniquely balanced discus feed with a blend of crumbled and granulated feeds that is crushable to any size.</li><li>Assures high water stability with crushable feed for fry to adults.</li><li>Contains Antarctic krill, a rich and sustainably procured protein source for added flavor and palatability</li><li>Discus colors are enhanced through natural sources of Astaxanthin.</li><li>Slowly sinking granules for optimum feed intake</li></ul>', '', 'published', '[\"intan-bits-600x600.png\"]', NULL, NULL, 0, 0, 0, 0, 1, 6, 0, 0, 390, 351, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 5, '2024-09-05 14:45:35', '2024-10-05 14:41:26', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'intan-bits-600x600.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(101, 'Intan Bits slowly sinking crumble 120gm', '<p class=\"fw600\" style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Slow Sinking Crushable Crumble</p><p style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Szie # 1.4 mm – 1.7 mm Dia</p><ul><li>Uniquely balanced discus feed with a blend of crumbled and granulated feeds that is crushable to any size.</li><li>Assures high water stability with crushable feed for fry to adults.</li><li>Contains Antarctic krill, a rich and sustainably procured protein source for added flavor and palatability</li><li>Discus colors are enhanced through natural sources of Astaxanthin.</li><li>Slowly sinking granules for optimum feed intake</li></ul>', '', 'published', '[\"intan-bits-600x600-400x400.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 369, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 7, '2024-09-06 16:23:30', '2024-10-05 14:41:08', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'intan-bits-600x600-400x400.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(102, 'Intan Cichlid Pellets (Small)55gm', '<p style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><span>Intan Cichlid Pellets (Small Floating Pellets), a Highly Nutritious Ornamental Fish Food with 45% protein, are formulated to provide a high-protein, balanced diet for all types of small &amp; big Cichlids. These pellets include fresh fish &amp; Antarctic krill to enhance flavour &amp; palatability. Natural Astaxanthin derived from krill helps to highlight the unique colour patterns of a variety of fish. Additionally, natural ingredients like marigolds, garlic, &amp; algae not only enhance colour patterns but also strengthen the immune system.</span></p><p style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">– High protein content to meet the nutritional demands of cichlids<br>– Contains “Fresh fish” in the formula to ensure robust health &amp; longevity of fish<br>– Improves the vivid colour patterns<br>– Enhances natural immunity against disease.</p>', '', 'published', '[\"untitled-design272-min-600x600.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 180, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 6, '2024-09-06 16:31:10', '2024-10-05 14:40:50', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'untitled-design272-min-600x600.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(103, 'AQUATIC VENTUREZ Blood Worms | 20g', '<p style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong class=\"uppercase\" style=\"font-weight:bolder;\">AQUATIC VENTUREZ Blood Worms</strong><br>This freeze-dried Blood Worms are genuine bloodworms, not mosquito larvae, so their ability to enhance color and growth is exceptional. High protein content makes it particularly effective as a conditioning food for breeding freshwater fish.</p><p style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Feeding Instructions</strong><br>Feed daily. Feed as much as the fish can eat within 2 minutes of feeding. Please remove the left-over feed immediately.</p><p style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Ingredients</strong><br>Blood Worms</p><p style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Nutritional composition</strong><br>Crude Protein: 55% | Crude Fat: 3% | Crude Fiber: 5% | Moisture: 5%</p>', '', 'published', '[\"aquatic-venturez-blood-worms-20g.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, 15, 0, 0, 300, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 6, '2024-09-07 20:31:58', '2024-10-07 13:02:23', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'aquatic-venturez-blood-worms-20g.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(104, 'Intan Faux Worms Medium 70 gm', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Intan Faux Worm Sticks (Slowly Sinking Sticks), a Highly Nutritious Ornamental Fish Food with 46% protein, are specially formulated for all types of fish including Discus, Loaches, Large Tetras &amp; Small Cichlids. These sticks are designed to mimic the shape of live worms, providing a safer alternative to live feed, which can be messy &amp; difficult to obtain. The consumption of live foods can increase the risk of parasitic loads &amp; microbial infections in fish &amp; their environments. Our delightful ‘faux-worm’ formulation offers excellent nutrition that is tasty, healthy &amp; safe while effectively mimicking the appeal of live worms.</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">“Faux-worms”, a fabulous mimic food<br>– Live food replacement that is just as palatable<br>– Natural colour enhancement with sustainable sources of Antarctic krill<br>– Low water turbidity<br>– Garlic fights parasites &amp; strengthens immunity</p>', '', 'published', '[\"intan-faux-worms-70-gm-min-600x600-1.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 351, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 6, '2024-09-07 20:34:11', '2024-10-05 14:40:21', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'intan-faux-worms-70-gm-min-600x600-1.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(105, 'Intan Goldfish Pellets (Big)140gm', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><span>Intan Goldfish Pellets (Big Floating Pellets), a Highly Nutritious Ornamental Fish Food with 42% protein, are specially formulated for all varieties of Goldfish, including Ryukin, Red Cap, Ranchu &amp; Lionhead. These pellets are made with highly nutritious ingredients to ensure maximum intake &amp; nutrient absorption while minimising water pollution. Recognising that Goldfish prefer natural foods like water plants, the formula includes algae &amp; yeast as suitable alternatives.</span></p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">– A special combination of ingredients, balanced to meet the specific nutritional</p><div class=\"product__description rte quick-add-hidden\" style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><p><span>meet the specific nutritional needs of Goldfish</span> <br><span>– Contains beta-carotene &amp; paprika for boosting the natural colours</span> <br><span>– No artificial colours or additives</span> <br><span>– Antarctic krill for added flavour &amp; palatability.</span></p></div>', '', 'published', '[\"untitled-design249-min-600x600.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 342, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 4, '2024-09-07 20:47:47', '2024-10-05 14:40:09', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'untitled-design249-min-600x600.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(106, 'Intan Guppy Pellets Medium 60 gm', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Intan Guppy Pellets (Floating Pellets), a Highly Nutritious Ornamental Fish Food with 40% protein, are specially formulated for different varieties of Guppies &amp; small surface-eating fish to match their natural diet. These pellets are made from high-quality ingredients of both plant &amp; animal origin, blended together to provide wholesome nutrition that is easily digestible by their short digestive tracts. Considering that guppies have small, upward-shaped mouths, the small size of our pellets makes them easy for these fish to consume.</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Scientifically formulated diet for promoting vitality, digestibility &amp; immunity<br>– Added Astaxanthin from natural ingredients to enhance their vivid colours<br>– The small size of our guppy pellets enables ease of intake<br>– An omnivorous diet with a balanced mix of animal &amp; plant protein</p>', '', 'published', '[\"intan-guppy-pellets-min-600x600-1.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 162, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 7, '2024-09-07 20:51:42', '2024-10-05 14:39:55', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'intan-guppy-pellets-min-600x600-1.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(107, 'Intan Herbivore Wafers (Big)190gm', '<p><span style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-size:16px;\"><span>Intan Herbivore Wafers (Big Sinking Wafers), a Highly Nutritious Ornamental Fish Food with 30% protein, are specially crafted for all herbivorous fish, including Mollies, Mbunas &amp; Plecos. These wafers are made with the finest quality leafy greens &amp; sustainably sourced vegetables. Containing high levels of fiber &amp; multivitamins, they promote excellent digestion, reduce inflammation, &amp; strengthen the immune system. Additionally, the high level of spirulina in the feed provides significant amounts of antioxidant pigments, such as phycocyanin &amp; carotenoids, enhancing the fishes’ colour &amp; increasing their nutrient absorption. High levels of Spirulina</span>  </span> <br><span style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-size:16px;\"><span>– Excellent feed intake &amp; digestibility</span>  </span> <br><span style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-size:16px;\"><span>– 100% vegetarian food</span>  </span> <br><span style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-size:16px;\"><span>– Uniquely formulated herbivore diet blended using high-quality mixed vegetables</span>  </span> <br><span style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-size:16px;\"><span>– Low water turbidity</span>  </span></p>', '', 'published', '[\"untitled-design250-min-600x600.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 504, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 7, '2024-09-09 12:27:31', '2024-10-05 14:39:23', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'untitled-design250-min-600x600.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(108, 'Intan Micro Bits large (140gm)', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Slowly Sinking Crumble – Dia 0.4mm</p><ul><li>High water stability</li><li>Addition of garlic as an immunostimulant</li><li>High Palatability</li><li>Antartic krill for added nutrition and flavor</li><li>Ideal for small mouth fish</li></ul><div class=\"suitable-text\" style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">Suitable for fish with small mouths like Killifish, Tetras, Rasboras, Danios etc</div>', '', 'published', '[\"intan-micro-bits-large-600x600.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 6, 0, 0, 396, NULL, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 3, '2024-09-09 12:29:33', '2024-10-05 14:38:46', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'intan-micro-bits-large-600x600.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
