(192, 'Echinodorus Joyo Red', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">An attractive hybrid variety with ruby red lanceolate leaves.</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Plant Difficulty</strong> : Easy</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Light Requirement </strong>: Low</p>', '', 'published', '[\"echinodorus-joyo-red-min.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, NULL, 0, 0, 140, 110, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 2, '2024-09-10 16:04:27', '2024-10-03 15:45:06', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'echinodorus-joyo-red-min.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0);
