(273, 'Lobelia Cardinalis Growow Tc Plant', '<p><span style=\"background-color:rgb(255,255,255);color:rgb(105,105,105);font-size:16px;\"><span>Lobelia Cardinalis is a light green stem plant that has an appealing plate of mixed green-like leaves. When grown emersed, the leaves can be purple, but when submerged, they are completely light green with just a hint of purple in very high light. </span> </span></p>', '', 'published', '[\"lobelia-cardinalis-growow-tc-plant-min.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, NULL, 0, 0, 300, 250, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 2, '2024-09-11 13:27:48', '2024-10-06 13:34:52', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'lobelia-cardinalis-growow-tc-plant-min.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(274, 'AQUATIC REMEDIES BACTONIL 220ML', '<figure class=\"table\" style=\"width:834px;\"><table class=\"woocommerce-product-attributes shop_attributes\" style=\"background-color:transparent;border-collapse:collapse;color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:0.9em;font-style:normal;font-weight:400;margin-bottom:1.618em;word-spacing:0px;\"><tbody><tr class=\"woocommerce-product-attributes-item woocommerce-product-attributes-item--weight\"><th class=\"woocommerce-product-attributes-item__label\" style=\"background-color:rgba(128,128,128,0.1);line-height:1.5;margin:0px;padding:8px;width:150px;\"><strong>Weight</strong></th><td class=\"woocommerce-product-attributes-item__value\" style=\"background-color:rgba(128,128,128,0.1);line-height:1.5;margin:0px;padding:0px;\"><i>220 kg</i></td></tr></tbody></table></figure>', '', 'published', '[\"aquatic-remedies-bactonil.png\"]', NULL, NULL, 0, 0, 0, 0, 0, 14, 0, 0, 420, 290, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 3, '2024-09-11 13:29:10', '2024-10-07 12:28:13', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'aquatic-remedies-bactonil.png', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(275, 'Ludwigia Arcuata dark red', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Description:</strong> Ludwigia Arcuata, also known as Needle Leaf Ludwigia, is a stunning aquatic plant celebrated for its vibrant hues and distinctive needle-like leaves. Belonging to the Onagraceae family, this species is native to North America and is popular among aquarists for its ability to add a striking splash of red or orange to freshwater aquariums. Ludwigia Arcuata’s slender stems and needle-shaped leaves create a visually dynamic and appealing contrast in aquascapes.</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Plant Information:</strong></p><ul><li><strong style=\"font-weight:bolder;\">Scientific Name:</strong> Ludwigia Arcuata</li><li><strong style=\"font-weight:bolder;\">Family:</strong> Onagraceae</li><li><strong style=\"font-weight:bolder;\">Origin:</strong> North America</li><li><strong style=\"font-weight:bolder;\">Difficulty Level:</strong> Moderate</li><li><strong style=\"font-weight:bolder;\">Lighting Requirements:</strong> Medium to High</li><li><strong style=\"font-weight:bolder;\">CO2 Requirement:</strong> Medium to High</li><li><strong style=\"font-weight:bolder;\">Temperature Range:</strong> 64-82°F (18-28°C)</li><li><strong style=\"font-weight:bolder;\">pH Range:</strong> 6.0-7.5</li><li><strong style=\"font-weight:bolder;\">Propagation:</strong> Cuttings</li></ul>', '', 'published', '[\"ludwigia-arcuata-dark-red-min.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, NULL, 0, 0, 140, 110, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 4, '2024-09-11 13:30:01', '2024-10-04 18:09:27', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'ludwigia-arcuata-dark-red-min.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(276, 'Ludwigia atlantis ” dark orange”', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\">This beautiful plant has golden yellow with green colored leaves and perfect for Dutch aquariums. Under high light it develops red stripes along the sides of leaves.</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Plant Difficulty</strong> : Medium</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Light Requirement</strong> :  Very Bright</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Plant Type</strong> :  Stem</p>', '', 'published', '[\"ludwigia-atlantis-dark-orange-min.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, NULL, 0, 0, 140, 110, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 2, '2024-09-11 13:31:11', '2024-10-04 18:10:04', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'ludwigia-atlantis-dark-orange-min.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NULL, 0),
(277, 'Ludwigia brevipes', '<p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Description:</strong> Ludwigia Brevipes, also known as Broadleaf Ludwigia or Red Ludwigia, is a captivating aquatic plant celebrated for its vibrant red or orange hues and distinctive broad leaves. Belonging to the Onagraceae family, this species is native to North and Central America. Ludwigia Brevipes adds a touch of elegance to freshwater aquariums with its eye-catching colors and graceful form. Its versatility and striking appearance make it a popular choice among aquarists for aquascaping.</p><p style=\"color:rgb(105,105,105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-weight:400;word-spacing:0px;\"><strong style=\"font-weight:bolder;\">Plant Information:</strong></p><ul><li><strong style=\"font-weight:bolder;\">Scientific Name:</strong> Ludwigia Brevipes</li><li><strong style=\"font-weight:bolder;\">Family:</strong> Onagraceae</li><li><strong style=\"font-weight:bolder;\">Origin:</strong> North and Central America</li><li><strong style=\"font-weight:bolder;\">Difficulty Level:</strong> Moderate</li><li><strong style=\"font-weight:bolder;\">Lighting Requirements:</strong> Medium to High</li><li><strong style=\"font-weight:bolder;\">CO2 Requirement:</strong> Medium to High</li><li><strong style=\"font-weight:bolder;\">Temperature Range:</strong> 64-82°F (18-28°C)</li><li><strong style=\"font-weight:bolder;\">pH Range:</strong> 6.0-7.5</li><li><strong style=\"font-weight:bolder;\">Propagation:</strong> Cuttings</li></ul>', '', 'published', '[\"ludwigia-brevipes-min-600x600.jpg\"]', NULL, NULL, 0, 0, 0, 0, 0, NULL, 0, 0, 140, 110, NULL, NULL, 0.00, 0.00, 0.00, 0.00, 0, 2, '2024-09-11 13:31:58', '2024-10-04 18:10:33', 'in_stock', 3, 'Botble\\ACL\\Models\\User', 'ludwigia-brevipes-min-600x600.jpg', 'physical', NULL, NULL, 0, 0, 0, 0, NULL, NUL