INSERT INTO `ec_products_translations` (`lang_code`, `ec_products_id`, `name`, `description`, `content`) VALUES
('bn_BD', 235, 'Hygrophila polysperma rosenervig', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Description:</strong>&nbsp;Hygrophila polysperma “Rosanervig” is a captivating variation of the classic Water Wisteria, known for its vibrant and distinctive coloration. This aquatic plant, a member of the Acanthaceae family, originates from Southeast Asia. Its name “Rosanervig” refers to the pink veins that adorn its leaves, adding a delightful touch of color to freshwater aquariums. With its feathery foliage and striking hues, this variant is a popular choice among aquarists seeking to introduce a splash of color to their aquatic landscapes.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Plant Information:</strong></p><ul><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Scientific Name:</strong>&nbsp;Hygrophila polysperma “Rosanervig”</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Family:</strong>&nbsp;Acanthaceae</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Origin:</strong>&nbsp;Southeast Asia</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Difficulty Level:</strong>&nbsp;Easy</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Lighting Requirements:</strong>&nbsp;Low to High</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">CO2 Requirement:</strong>&nbsp;Low to Medium</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Temperature Range:</strong>&nbsp;68-82°F (20-28°C)</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">pH Range:</strong>&nbsp;6.0-7.5</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Propagation:</strong>&nbsp;Cuttings, Side Shoots</li></ul>', NULL),
('bn_BD', 236, 'THE 2HR AQUARIST ALL IN ONE APT1-ZERO 200ml', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">The 2Hr Aquarist All-In-One Fertiliser.</strong><br><strong style=\"box-sizing:border-box;font-weight:bolder;\">Richer Colors, Less Algae. Faster Results.</strong></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Dose 5ml per 100L four times a week or 3ml per 100L daily.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Comprehensive plant supplement, without nitrates and phosphates for tanks with more fish and new tanks using aquasoil.</p><div class=\"elementor-element elementor-element-2304ef90 elementor-widget elementor-widget-woocommerce-product-content\" style=\"--align-content:initial;--align-items:initial;--align-self:initial;--flex-basis:initial;--flex-direction:initial;--flex-grow:initial;--flex-shrink:initial;--flex-wrap:initial;--gap:initial;--justify-content:initial;--order:initial;--swiper-navigation-size:44px;--swiper-pagination-bullet-horizontal-gap:6px;--swiper-pagination-bullet-size:6px;--swiper-theme-color:#000;--widgets-spacing:20px 20px;-webkit-text-stroke-width:0px;align-content:var(--align-content);align-items:var(--align-items);align-self:var(--align-self);box-sizing:border-box;color:rgb(105, 105, 105);flex-basis:var(--flex-basis);flex-direction:var(--flex-direction);flex-grow:var(--flex-grow);flex-shrink:var(--flex-shrink);flex-wrap:var(--flex-wrap);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;gap:var(--gap);justify-content:var(--justify-content);letter-spacing:normal;order:var(--order);orphans:2;position:relative;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-id=\"2304ef90\" data-element_type=\"widget\" data-widget_type=\"woocommerce-product-content.default\"><div class=\"elementor-widget-container\" style=\"box-sizing:border-box;transition:background .3s,border .3s,border-radius .3s,box-shadow .3s,transform var(--e-transform-transition-duration,.4s);\"><p style=\"box-sizing:border-box;margin-block:0px 0.9rem;\">Tackle the most demanding plants, or just enjoy everyday magic in the simplest tank. The easiest way to unlock the true potential of your planted tank today.</p></div></div>', NULL),
('bn_BD', 237, 'Hygrophila Sp. Chai Growow Tc Plant', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">plant with a unique pink hue and low-growing bush habit. Its striking color makes it an ideal choice for aquascaping or providing a color accent in tanks.&nbsp;It&nbsp;is a mutation from Hygrophila&nbsp;Araguaia, in which it has a very vibrant coloration. It is best to place it into a matured tank.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Hygrophila lancea ‘Chai’ is a rare cultivar of Hygrophila lancea “Araguaia,” distinguishable by its distinct linear, curved leaves with a white to pink edge and green center. For best results, it requires strong lighting, CO2 supplementation, and adequate nutrient levels. This beautifully variegated stem plant grows slowly and requires occasional trimming to maintain its low, bushy growth. Easily propagated by cuttings.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Growth Rate:&nbsp;</strong>Slow</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Placement:&nbsp;</strong>Foreground</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Light Demand:&nbsp;</strong>High</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">CO2:&nbsp;</strong>High</p>', NULL),
('bn_BD', 238, 'THE 2HR AQUARIST ALL IN ONE APT3-COMPLETE 200ml', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">The 2Hr Aquarist All-In-One Fertiliser.</strong><br><strong style=\"box-sizing:border-box;font-weight:bolder;\">Richer Colors, Less Algae. Faster Results.</strong></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Dose 5ml per 100L four times a week or 3ml per 100L daily.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Flagship plant supplement. Comprehensive macro, micro and trace elements. Richer colours, faster growth, less algae.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Tackle the most demanding plants, or just enjoy everyday magic in the simplest tank. The easiest way to unlock the true potential of your planted tank today.</p>', NULL),
('bn_BD', 239, 'The 2Hr Aquarist APT 1 Zero 300ml', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><span style=\"box-sizing:border-box;\" data-sanitized-data-mce-fragment=\"1\"><strong style=\"box-sizing:border-box;font-weight:bolder;\" data-sanitized-data-mce-fragment=\"1\">The 2Hr Aquarist APT 1 Zero 300ml </strong>is for tanks with more fish, fewer plants. For new tanks (&lt;3 months) with aquasoil. Comprehensive nutrition without nitrates and phosphates for maximum algae control.</span></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" data-sanitized-data-mce-fragment=\"1\"><span style=\"box-sizing:border-box;\" data-sanitized-data-mce-fragment=\"1\">Tackle the most demanding plants, or just enjoy everyday magic in&nbsp;<strong style=\"box-sizing:border-box;font-weight:bolder;\" data-sanitized-data-mce-fragment=\"1\">new tanks with aquasoil</strong>, and aquariums with&nbsp;<strong style=\"box-sizing:border-box;font-weight:bolder;\" data-sanitized-data-mce-fragment=\"1\">more fish</strong>. The easiest&nbsp;way to unlock the true potential of your planted tank today</span></p>', NULL),
('bn_BD', 240, 'The 2Hr Aquarist APT Complete 300ml', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Tackle the most demanding plants, or just enjoy everyday magic in the simplest tank. The easiest way to unlock the true potential of your planted tank today.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Dose 5ml per 100L four times a week or 3ml per 100L daily.</strong></p>', NULL),
('bn_BD', 241, 'THE 2HR AQUARIST APT F-ALGAE TREATMENT 200ml', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">The smarter way to treat algae.</strong></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Especially effective for BBA, hair/string/fuzz and most forms of filamentous algae.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Gently biodegrades completely.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Spot-dose up to 1ml per 10L every 24 hours.</p>', NULL),
('bn_BD', 242, 'The 2Hr Aquarist APT Fix 300ml', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">The smarter way to treat algae.</strong><br>Especially effective for BBA, hair/string/fuzz and most forms of filamentous algae.<br>Gently biodegrades completely.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Spot-dose up to 1ml per 10L every 24 hour</p>', NULL),
('bn_BD', 243, 'THE 2HR AQUARIST APT P-WATER CONDITIONER 200ML', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">The 360<sup style=\"box-sizing:border-box;font-size:12px;line-height:0;position:relative;top:-0.5em;vertical-align:baseline;\">o</sup>&nbsp;water conditioner.</strong><br>Comprehensive and super-concentrated formula removes chlorine &amp; chloramines and detoxifies heavy metals, ammonia, nitrites and nitrates.<br>Contains soothing Aloe Vera extract.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Dose 1ml per 60L</strong><br>Dose up to 5X recommended dosage as an emergency tool to detoxify Ammonia.</p>', NULL),
('bn_BD', 244, 'The 2hr Aquarist APT Pure Water Conditioner', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Comprehensive and super-concentrated formula removes chlorine &amp; chloramines and detoxifies heavy metals, ammonia, nitrites and nitrates.<br>Contains soothing Aloe Vera extract.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Dose 1ml per 60L</strong></p>', NULL),
('bn_BD', 245, 'The 2HR Aquarist APT Sky (150 GMS)', NULL, '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Discover new possibilities with SKY-boosted water.<br>Enable shrimps and hardwater plants to thrive together with softwater plants*.<br>Replenish all vital minerals in RO/ RODI water with no negative altering of NPK, KH or pH.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Each 3.5g / 5ml per 60L adds 12ppm Calcium and 3.5ppm Magnesium (+2.5 dGH)</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Recommended: 15ml per 60L of RO/RODI water.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">*To grow softwater plants, RO/RODI water recommended if tap water measures &gt;2 dKH</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">FEATURES</strong></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">APT SKY resolves the key conundrum of how to increase water hardness (specifically as a GH booster) without altering NPK values (which interfere with the calibrated ratios of fertilisers) and KH (where higher values are not favoured by most commercial aquatic plants).</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">&nbsp;</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">INGREDIENTS</strong></p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Ca (Calcium): 21.5%<br>Mg (Magnesium): 5.4%<br>B (Boron): 7mg/L<br>Cu (Copper): 1mg/L<br>Fe (Iron): 0.06%<br>Mn (Manganese): 17mg/L<br>Mo (Molybdenum): 0.01mg/L<br>Zn (Zinc): 9mg/L<br>Seaweed extract &lt;1%</p>'),
('bn_BD', 246, 'VIVIFY', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">The Back 2 Nature Aqueous Series VIVIFY is a consortium of beneficial bacteria equally effective for both fresh water &amp; marine aquariums.</p><ul><li>VIVIFY when used, almost instantly helps in detoxifying the harmful ammonia &amp; nitrites by rapidly breaking them down into safe non-toxic form.</li><li>VIVIFY also rapidly helps in decomposing all organic &amp; nitrogenous wastes like fish waste and leftover food.</li><li>VIVIFY helps in improving the digestive &amp; immune systems, as well as the colour of fishes, shrimps, and other aquarium live forms.<strong style=\"box-sizing:border-box;font-weight:bolder;\">DOSAGE DIRECTIONS:</strong>Use 1 capful (5mL) VIVIFY for each 10 litres (2.6 gallons) of new aquarium water.For subsequent dosing, use 1 capful for each 20 litres (5.2 gallons) of water changed.For optimum performance use double than recommended.</li></ul>', NULL),
('bn_BD', 247, 'Hygrophila sp. Quadrivalvis Apple Red.', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Description:</strong>&nbsp;Hygrophila sp. Quadrivalvis “Apple Red” is a captivating aquatic plant prized for its distinctive red coloration and graceful growth pattern. Belonging to the Acanthaceae family, this species showcases vibrant red hues throughout its leaves, creating a striking contrast in freshwater aquariums. Originating from Southeast Asia, “Apple Red” is an excellent choice for aquarists seeking a visually appealing and colorful addition to their aquascapes.</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">Plant Information:</strong></p><ul><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Scientific Name:</strong>&nbsp;Hygrophila sp. Quadrivalvis “Apple Red”</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Family:</strong>&nbsp;Acanthaceae</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Origin:</strong>&nbsp;Southeast Asia</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Difficulty Level:</strong>&nbsp;Moderate</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Lighting Requirements:</strong>&nbsp;Medium to High</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">CO2 Requirement:</strong>&nbsp;Medium to High</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Temperature Range:</strong>&nbsp;68-82°F (20-28°C)</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">pH Range:</strong>&nbsp;6.0-7.5</li><li><strong style=\"box-sizing:border-box;font-weight:bolder;\">Propagation:</strong>&nbsp;Cuttings, Side Shoots</li></ul>', NULL),
('bn_BD', 248, 'FIREGLOW DUO 21W', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Fireglow DUO 21W :</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">●Super Flexible Stand<br>●Dual Round Panel LED with White and Blue<br>●ABS&nbsp; Body.<br>●Polycarbonate based Transparent Splash Guard.<br>●Support upto 12mm glass thickness</p>', NULL),
('bn_BD', 249, 'FIREGLOW ONELY 1OW', '<p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">FireGlow ONELY Clip LED 10W | 6500K</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">●Super Flexible Stand<br>●Single Round Panel LED with White and Blue<br>●ABS&nbsp; Body.<br>●Polycarbonate based Transparent Splash Guard.<br>●Support upto 12mm glass thickness</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">&nbsp;</p><p style=\"-webkit-text-stroke-width:0px;box-sizing:border-box;color:rgb(105, 105, 105);font-family:Poppins, sans-serif;font-size:16px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-block:0px 0.9rem;orphans:2;text-align:start;text-decora