INSERT INTO `pages` (`id`, `name`, `content`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Homepage', '<shortcode>[simple-slider key=\"home-slider\" show_newsletter_form=\"yes\"][/simple-slider]</shortcode><shortcode>[featured-product-categories title=\"Top Categories\"][/featured-product-categories]</shortcode><shortcode>[theme-ads ads_1=\"IZ6WU8KUALYD\" ads_2=\"ILSFJVYFGCPZ\" ads_3=\"ILSDKVYFGXPH\"][/theme-ads]</shortcode><shortcode>[popular-products title=\"Popular Products\" per_row=\"5\" limit=\"10\" enable_lazy_loading=\"yes\"][/popular-products]</shortcode><shortcode>[best-flash-sale title=\"Daily Best Sells\" flash_sale_id=\"5\" ads=\"IZ6WU8KUALYG\"][/best-flash-sale]</shortcode><shortcode>[flash-sale flash_sale_1=\"1\" flash_sale_2=\"2\" flash_sale_3=\"3\" flash_sale_4=\"4\" title=\"Deals Of The Day\" flash_sale_popup_id=\"1\"][/flash-sale]</shortcode><shortcode>[top-products-group tabs=\"top-selling,trending-products,recent-added,top-rated\" top_selling_in_days=\"365\" enable_lazy_loading=\"yes\"][/top-products-group]</shortcode><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p>', 1, NULL, 'homepage', '', 'published', '2022-03-16 02:41:33', '2024-10-28 17:46:48'),
(6, 'Contact Us', '<p style=\"text-align:center;\"><span style=\"font-family:\'Lucida Sans Unicode\', \'Lucida Grande\', sans-serif;font-size:19px;\"><span><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Get in touch and let us know how we can help.</strong></span></span></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\"><span style=\"font-size:24px;\"><span><strong>&nbsp; &nbsp; &nbsp; &nbsp; Get in touch</strong></span></span><br><br><span style=\"font-size:18px;\"><span>If you have any questions fill out the form below and we will get back to you within 48 hours. Or, feel free to drop us a email at : info.lmpetshop@gmail.com / call us at : +9186971 03717</span></span></p><p style=\"text-align:center;\">&nbsp;</p><shortcode>[google-map]Little Mermaid Gallery, 21/4, Russa Rd South 3rd Ln 21/4, Russa Rd South 3rd Ln, Netajinagar, Rajendra Prasad Colony, Tollygunge, Kolkata, West Bengal 700033 [/google-map]</shortcode><p>&nbsp;</p><p>&nbsp;</p><shortcode>[google-map]502 New Street Little Mermaid 4.B, SR Das Rd, Lake, Lake Range, Kalighat, Kolkata, West Bengal 700026 [/google-map]</shortcode><shortcode>[our-offices][/our-offices]</shortcode><figure class=\"image\"><img style=\"aspect-ratio:1200/1200;\" src=\"https://aqua1.teminos.com/storage/little-mermaid-banners-2.png\" alt=\"little-mermaid-banners-2.png\" width=\"1200\" height=\"1200\"></figure><shortcode>[contact-form][/contact-form]</shortcode>', 1, 'lm-about-us.png', 'blog-big', '', 'published', '2022-03-16 02:41:33', '2024-10-28 17:50:57'),
(7, 'About Us', '<h1 style=\"text-align:center;\"><span style=\"color:hsl(90,75%,60%);font-size:24px;\"><i><strong>Little Mermaid</strong></i></span></h1><figure class=\"image\"><img src=\"https://aqua1.teminos.com/storage/whatsapp-image-2023-10-09-at-172819.jpeg\" alt=\"WhatsApp-Image-2023-10-09-at-17.28.19\" loading=\"lazy\"></figure><p style=\"text-align:center;\"><span style=\"background-color:rgb(255,255,255);color:rgb(51,51,51);font-size:16px;\"><i><span><strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; The Founders: Mr. Indranil Chowdhury &amp; Mrs. Rishita Chowdhury</strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span> &nbsp;</i></span> &nbsp;</p><div class=\"raw-html-embed\"></div><h4 style=\"line-height:1.38;text-align:center;\" dir=\"ltr\">&nbsp;</h4><h2 style=\"text-align:center;\"><span style=\"background-color:transparent;color:hsl(0,0%,0%);font-size:22px;\"><span><strong>Your #TankMatesForLife</strong>&nbsp;&nbsp;</span> &nbsp;</span> &nbsp;<span style=\"background-color:transparent;color:#666666;font-size:15px;\"><span>&nbsp;</span> &nbsp;</span></h2><h4 style=\"line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#666666;\"><span>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span> &nbsp;</span></h4><p style=\"line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-family:\'Trebuchet MS\', Helvetica, sans-serif;font-size:20px;\"><span>Little Mermaid was established in 2015 to cater to the needs&nbsp; &nbsp;&nbsp;</span> &nbsp;</span></p><p style=\"line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-family:\'Trebuchet MS\', Helvetica, sans-serif;font-size:20px;\"><span>&nbsp;of aquarium hobbyists in Kolkata. With two thriving outlets in Kolkata, West Bengal,&nbsp; &nbsp;&nbsp;</span> &nbsp;</span></p><p style=\"line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-family:\'Trebuchet MS\', Helvetica, sans-serif;font-size:20px;\"><span>&nbsp;we\'ve been fortunate&nbsp; &nbsp; &nbsp;</span> &nbsp;</span></p><p style=\"line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-family:\'Trebuchet MS\', Helvetica, sans-serif;font-size:20px;\"><span>to receive overwhelming support from our community. Our diverse inventory, fresh aquatic plants, and healthy ornamental fish have made us a favorite among local hobbyists. Inspired by this positive response, we decided to expand our reach and bring the same quality and passion to a broader audience through our new e-commerce portal. Now, you can enjoy the Little Mermaid experience from the comfort of your home!&nbsp; &nbsp;&nbsp;</span> &nbsp;</span></p><p>&nbsp;</p><p style=\"line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-family:\'Trebuchet MS\', Helvetica, sans-serif;font-size:18px;\"><span>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></p><p style=\"text-align:center;\"><span style=\"background-color:#ffffff;color:hsl(90,75%,60%);font-size:24px;\"><i><span><strong>&nbsp; &nbsp; &nbsp; Why choose us</strong>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</i></span></p><p style=\"text-align:center;\"><span style=\"background-color:#ffffff;color:#4ca1a6;font-size:23px;\"><i><span>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</i></span></p><p style=\"line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;\"><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</span> &nbsp;</span> &nbsp;<span style=\"background-color:transparent;color:#1a1a1a;font-size:22px;\"><span> &nbsp; &nbsp;<img class=\"image_resized\" style=\"aspect-ratio:75/49;width:10.69%;\" src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXfcjCc31pt48XypKQB0wurubgFbcjC18jveHqWSKd-b7ZWEeTKmo3EDWXnJqcJqfvOGZXiwe3JBPPQsEXoXQ5eAC1gtha0tLrHb3Th3BTnNurTGCEithfJNh9CPDDOrABKPLSnZMG25uF9BkqmeSfkTwYnW?key=kaY5oNHI26V89wym4LjnVQ\" alt=\"Aquarium_setup_img\" width=\"75\" height=\"49\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></p><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:#ffffff;color:#e6994d;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;</strong></span> <span><strong>One-Stop Shop&nbsp;&nbsp;</strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span><strong>&nbsp;From beginner kits to advanced gear, we have it all to make your fish tank flourish.&nbsp;&nbsp;&nbsp;</strong> &nbsp;</span> &nbsp;</span> &nbsp;<span style=\"font-size:22px;\">&nbsp;</span> &nbsp;<span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span> &nbsp;</span></h5><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-size:22px;\"><span><strong>&nbsp;</strong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span> &nbsp;</span></h5><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img class=\"image_resized\" style=\"aspect-ratio:49/49;width:6.76%;\" src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXcn87rBZwyyyo9LNVjUi5VnejdRnQPyQb82Nshwyfd3EfPo46fmKeOsRmEnzyOAGHARgmbc8hYeZ0JnIVI7Pf2A3Sb0GG90RTGhK6XOOTPFs0TUJWy4s6F7_COI9H1Gw2K1p0IE-S77BVDkWeQCrUcHNWi_?key=kaY5oNHI26V89wym4LjnVQ\" alt=\"certificate.png\" width=\"49\" height=\"49\"></strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#e6994d;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</strong></span> &nbsp;</span> &nbsp;<span style=\"font-size:22px;\">&nbsp;</span> &nbsp;<span style=\"background-color:transparent;color:#e6994d;font-size:22px;\"><span><strong> &nbsp; &nbsp;Reliable Genuine Products&nbsp;&nbsp;</strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;We offer only quality products we believe in.&nbsp;&nbsp;&nbsp;</strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><p style=\"text-align:center;\">&nbsp;</p><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#1a1a1a;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <img class=\"image_resized\" style=\"aspect-ratio:49/49;width:8.66%;\" src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXeeiOL3Q-G_jbVohxlA-Ki5YXG7biB1RlG-s8TE3Be8aevHhVXv6qXOxA_EWHvvX_kKBDrUNkhDL-QnL0L4RaAjiC6gJAtTL78JXUa4zbkGBWnnLHJ85Jn1ks2GcdcvC9R0xnG05j_gfZ0vXTj0W1WkxBGZ?key=kaY5oNHI26V89wym4LjnVQ\" alt=\"Fast and safe shipping\" width=\"49\" height=\"49\"></strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#e6994d;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</strong></span> &nbsp;</span> <span style=\"background-color:transparent;color:#e6994d;font-size:22px;\"><span><strong>Quick Delivery&nbsp;&nbsp;</strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#e6994d;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;</strong></span> </span><span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span>Get your aquarium supplies delivered quickly and safely.&nbsp;</span> &nbsp;</span> &nbsp;<span style=\"font-size:22px;\">&nbsp;</span> &nbsp;<span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><p style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"font-size:22px;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;<br><span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<img class=\"image_resized\" style=\"aspect-ratio:49/49;width:6.72%;\" src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdU7Pl2TBmTcT4-EWMgPrdE8wS7bQCphIjyiNYqJFAftXtKVKdq6fjwcuhstPd0eRE2LQ_yJBST64BzwF3UjTn9-hvmfdhx6xUem_O6M2qFz8U56lZYPABjxMvBncN3bsiv8RyNNKFcO0K65I-N6j238aju?key=kaY5oNHI26V89wym4LjnVQ\" alt=\"Chat support\" width=\"49\" height=\"49\"> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></p><h5 style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#e6994d;font-size:22px;\"><span><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</strong></span> <span><strong>Responsive Assistance&nbsp;&nbsp;</strong> &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></h5><p style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;<strong>Get professional recommendations and customer service through chat.</strong>&nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span></p><p style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\">&nbsp;</p><h1 style=\"text-align:center;\"><span style=\"background-color:transparent;color:hsl(0,0%,0%);font-size:24px;\"><span><strong>Our Delivery Partner</strong></span> &nbsp;</span></h1><p style=\"background-color:#ffffff;line-height:1.38;text-align:center;\" dir=\"ltr\"><span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</span> &nbsp;</span> &nbsp;<span style=\"font-size:22px;\">&nbsp;</span> &nbsp;<span style=\"background-color:transparent;color:#696969;font-size:22px;\"><span>&nbsp;</span> &nbsp;</span></p><figure class=\"image\"><img style=\"aspect-ratio:1200/351;\" src=\"https://aqua1.teminos.com/storage/image-2.png\" alt=\"image-2.png\" width=\"1200\" height=\"351\"></figure><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p>', 1, 'planted-tank-supplies-150x150.png', 'blog-list', '', 'published', '2022-03-16 02:41:33', '2024-10-28 17:38:19');
